/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  return api.state.projectData?.miningState?.value !== "AVAILABLE";
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  const miningState = api.state.projectData?.miningState?.value;
  const isErrorOrCancelled = miningState === "ERROR" || miningState === "CANCELLED";
  return !(isErrorOrCancelled && api.state.isAvailableVersionPresent);
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const projectNumber = api.state?.projectData?.projectNumber;
    if(projectNumber){
    return [{
        "label": helpers.translateSync("Number"),
        "value": {
            "type": "string",
            "value": projectNumber
        }
    }];
    }
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const statuses = {
        DRAFT: 'warning',
        NEW: 'positive',
        PUBLISHED: 'info',
        RETIRED: 'critical',
    };
    const projectStatus = api.state?.projectData?.status?.label;
    return [{
        "label": helpers.translateSync("Project Status"),
        "value": [{
            "label": projectStatus,
            "type": "highlighted-value",
            'color': statuses[api.state?.projectData?.status?.value] || 'info',
        }]
    }];
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const statuses = {
        AVAILABLE: 'positive',
        CANCELLED: 'low',
        ERROR: 'critical',
        MINING_DATA: 'high',
        SCHEDULED: 'low',
        NEW: 'positive',
    };
    const projectState = api.state?.projectData?.miningState?.label;
    return [{
        "label": helpers.translateSync("Mining state"),
        "value": [{
            "label": projectState,
            "type": "highlighted-value",
            'color': statuses[api.state?.projectData?.miningState?.value],
            'showIcon': false
        }]
    }];
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const createdBy = api.state?.projectData?.createdBy;
    if(createdBy){
    return [{
        "label": helpers.translateSync("Created by"),
        "value": {
            "type": "string",
            "value": createdBy
        }
    }];
}
}

