/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  const automatedFindingsCount = api.data.look_up_automated_finding_def?.results?.length || 0;
  const ruleBasedFindingsCount = api.data.look_up_finding_def?.results?.length || 0;
  const totalFindingsCount = Number(automatedFindingsCount) + Number(ruleBasedFindingsCount);

	return helpers.translateSync('Total applied: {0} • Rule based: {1} • Automated: {2}', totalFindingsCount, ruleBasedFindingsCount, automatedFindingsCount);
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  return {
    "columns": [
        {
            "key": "name",
            "label": helpers.translateSync("Finding definition name"),
            "metadata": {
                "isFilterable": true,
                "isGroupable": true,
                "isSortable": true
            }
        },
        {
            "key": "type",
            "label": helpers.translateSync("Type"),
            "metadata": {
                "isFilterable": true,
                "isGroupable": true,
                "isSortable": true
            },
            "width": "200px",
        },
        {
            "key": "category",
            "label": helpers.translateSync("Category"),
            "metadata": {
                "isFilterable": true,
                "isGroupable": true,
                "isSortable": true
            },
            "type": "string"
        },
        {
            "key": "impacted_kpis",
            "label": helpers.translateSync("Impacted KPI(s)"),
            "metadata": {
                "isFilterable": true,
                "isGroupable": true,
                "isSortable": true
            },
            "type": "string"
        },
        {
            "key": "sys_updated_on",
            "label": helpers.translateSync("Updated on"),
            "metadata": {
                "isFilterable": true,
                "isGroupable": false,
                "isSortable": true
            },
            "type": "string"
        },
        {
            "key": "sys_updated_by",
            "label": helpers.translateSync("Updated by"),
            "metadata": {
                "isFilterable": true,
                "isGroupable": true,
                "isSortable": true
            },
            "type": "string"
        }
    ]
};
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    if (api.state.projectData.ismining) {
        return helpers.translateSync("View Progress");
    } else if(api.state.projectData?.miningState?.value == "NEW"){
        return helpers.translateSync("Mine Project");
    }else{
        return helpers.translateSync("Remine Project");
    }
}

