function evaluateEvent({api, event}) {
	const projectData = api.state.projectData;
    const isEvaluation = projectData?.source?.startsWith("FREEMIUM");

	if (isEvaluation) {
        return {
            event: "Eval project sample mining",
            value: {
                Source: "Project Guided Setup"
            }
        };
    }
	const miningType = api.state.projectData?.miningState?.value == "NEW" ? "Mine Project" : "Remine Project";
	return {
		event: api.state.fullMine ? "Full Mining" : "Sample Mining",
		value: {
			Source: "Project Guided Setup",
			Type: miningType,
			ActionType: "Click",
			'Page Id': "Overview"
		}
	};
})

